import{_ as a,o as n,c as e,a2 as o}from"./chunks/framework.BM5YPQmL.js";const O=JSON.parse('{"title":"系统总览：四个组件及其协作方式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/system-map.md","filePath":"zh/arch/system-map.md"}'),t={name:"zh/arch/system-map.md"};function p(l,s,c,d,i,r){return n(),e("div",null,[...s[0]||(s[0]=[o(`<h1 id="系统总览-四个组件及其协作方式" tabindex="-1">系统总览：四个组件及其协作方式 <a class="header-anchor" href="#系统总览-四个组件及其协作方式" aria-label="Permalink to &quot;系统总览：四个组件及其协作方式&quot;">​</a></h1><p>Open Cube OS 不是一个程序。四个独立链接的二进制文件共享同一个仓库、 同一个版本字符串，并通过固定的物理内存契约彼此传递控制权。本页是 全景视图：每个组件是什么、协作图、版本链、把各方绑定在一起的物理 内存地图，以及系统支持的每一种引导模式。深度解析：加载器链见 <a href="./boot-flow.html">boot-flow.md</a>，跨组件的合谋机制见 <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>，文件树见 <a href="./tree-map.html">tree-map.md</a>。</p><h2 id="四个组件" tabindex="-1">四个组件 <a class="header-anchor" href="#四个组件" aria-label="Permalink to &quot;四个组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>位置</th><th>身份</th></tr></thead><tbody><tr><td><strong>OCBL</strong></td><td><code>ocbl/</code></td><td>引导加载器（BIOS 与 UEFI 两种形态）。在 3.0.0-WP05 B5-7 中取代了发布 ISO 上的 GRUB。扫描每块磁盘，分类每个可引导卷，运行 10 秒菜单，并向所选内核递交与 GRUB 完全一致的 multiboot2 状态。</td></tr><tr><td><strong>OCSE</strong></td><td><code>ocse/</code></td><td>&quot;OpenCubeOS Setup Environment&quot;——安装器。一个小型独立内核，<strong>从 git tag v1.0.0 vendor 内嵌而来</strong>（143 个文件，有意冻结：见 <code>ocse/VENDORING.md</code>），自带一套驱动（ATA/AHCI/NVMe/virtio/USB/ACPI）、一个 40 命令 shell（OCSECL）、一个 9 步 GUI 向导和一个 8 步安装状态机。</td></tr><tr><td><strong>OCOS</strong></td><td><code>ocos/</code></td><td>主系统：L0 服务内核（<code>ocos/kernel/</code>）、驱动层（<code>ocos/drivers/</code>）、24 个服务家族（<code>ocos/services/</code>）、ring 3 API 契约（<code>ocos/interface/</code>）以及 284 个内嵌 ring 3 应用程序（<code>ocos/l1apps/</code>）。运行中系统的一切。</td></tr><tr><td><strong>OCIRE</strong></td><td><code>ocire/</code></td><td>独立恢复内核。OCOS 的 L0 <em>对等体</em>——自有 include 路径、自有链接脚本、不含任何 OCOS 头文件（WP-01 独立性规则）。自有 ATA 驱动、自有 FAT12/32 代码、自有 SHA-256、自有控制台、自有 IDT、自有 ACPI、自有 6300ESB 看门狗。以监督者（<code>ocire.mode=sup</code>）或完整恢复 shell 引导，kexec OCOS，并在 OCOS 无法引导时修复机器。</td></tr></tbody></table><p>源代码层面只有三样东西共享：<code>include/ocbl_state.h</code>（OCBL、OCOS、 OCIRE 三方逐字节共享的引导状态契约）、中文字体数据（OCIRE 的 <code>ocire/generated/ocire_cn_font_data.c</code> 由 <code>ocse/chinese/chinese_font_data.c</code> 生成）以及 OCIRE 日志代理编译所依据的 L1 ABI（是 ABI，不是 include）。</p><h2 id="协作图" tabindex="-1">协作图 <a class="header-anchor" href="#协作图" aria-label="Permalink to &quot;协作图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> power-on</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    v</span></span>
<span class="line"><span> +--------------------------------------------------------------+</span></span>
<span class="line"><span> | OCBL  (BIOS stage1 @0x7C00 -&gt; core @0x7E00  /  UEFI PE app)  |</span></span>
<span class="line"><span> |  * 6-class volume scanner: OCSE OCOS OCIRE WINDOWS LINUX     |</span></span>
<span class="line"><span> |    GENERIC  (+ synthesized Shutdown row)                     |</span></span>
<span class="line"><span> |  * 3-key 10 s menu (Up/Down/Enter only), serial-mirrored     |</span></span>
<span class="line"><span> |  * A/B slot judgment on the first OCOS volume (flag files)   |</span></span>
<span class="line"><span> |  * boot-state monitor: reads 0x98000/0x9B000, arms 6300ESB   |</span></span>
<span class="line"><span> |  * auto-route: pending BOOT_FAILED record -&gt; OCIRE one-shot  |</span></span>
<span class="line"><span> +----+----------------+----------------+----------------+------+</span></span>
<span class="line"><span>      |                |                |                |</span></span>
<span class="line"><span>   OCOS             OCIRE             OCSE          foreign VBR/ESP</span></span>
<span class="line"><span>      |                |                |                |</span></span>
<span class="line"><span>      v                v                v                v</span></span>
<span class="line"><span> mb2 handoff      mb2 handoff      mb2 handoff      chainload</span></span>
<span class="line"><span> EAX=0x36D76289   EAX=0x36D76289   EAX=0x36D76289   (0x7C00 jump /</span></span>
<span class="line"><span> EBX=MBI@0x50000  EBX=MBI@0x50000  EBX=MBI@0x50000   LoadImage)</span></span>
<span class="line"><span> 32-bit, pg off    32-bit, pg off   32-bit, pg off</span></span>
<span class="line"><span>      |                |                |</span></span>
<span class="line"><span>      |         OCIRE kexec           +--&gt; installs OCOS disks:</span></span>
<span class="line"><span>      |         OCOS ELF -&gt; [1MiB,8MiB)     ocbl-install writes the</span></span>
<span class="line"><span>      |         MBI rebuilt @0x80000        OCBL MBR flavor, mkfs.fat32,</span></span>
<span class="line"><span>      |         agent module appended       tar payload, boot flags</span></span>
<span class="line"><span>      |                |</span></span>
<span class="line"><span>      v                v</span></span>
<span class="line"><span> +-------------+  +--------------------+</span></span>
<span class="line"><span> | OCOS kmain  |  | OCIRE supervisor   |</span></span>
<span class="line"><span> | boot chain  |  | mailbox WAIT_SIGNAL|</span></span>
<span class="line"><span> | 1/4 kernel  |  | arm wdt 60 s       |</span></span>
<span class="line"><span> | 2/4 drivers |  | kexec OCOS -------&gt;|  (OCOS boots with</span></span>
<span class="line"><span> | 3/4 service |  +--------------------+   oc.* embed facts)</span></span>
<span class="line"><span> | 4/4 iface   |</span></span>
<span class="line"><span> | L1 ush      |  OCOS first seconds:</span></span>
<span class="line"><span> |  ...        |   ocembed_boot_confirm(): mailbox SIGNAL_OK,</span></span>
<span class="line"><span> +-------------+   disarm i6300esb, spawn ocire_guard agent,</span></span>
<span class="line"><span>                   write-protect the whole recovery disk.</span></span></code></pre></div><p>反向边与正向边同样重要：当 OCOS 在引导过程中死亡时，6300ESB 看门狗 复位机器，OCBL 读取 0x9B000 事后记录，依据 0x98000 阶段孤岛判定失败， 并在无任何菜单交互的情况下把下一次引导路由进 OCIRE（完整链路见 <a href="./crash-recovery.html">crash-recovery.md</a>）。</p><h2 id="版本链" tabindex="-1">版本链 <a class="header-anchor" href="#版本链" aria-label="Permalink to &quot;版本链&quot;">​</a></h2><p>同一个 <code>OC_RELEASE_VERSION</code> 和同一个 <code>OC_KERNEL_BUILD</code> 流入全部四个 横幅——四个组件在构造上即步调一致地发布（<code>Makefile</code> 第 90/103-104 行）：</p><div class="language-make vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">make</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OC_RELEASE_VERSION ?= 3.0.0-NAK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OC_KERNEL_BUILD_OFFSET := 21</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OC_KERNEL_BUILD ?= </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expr </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">(git rev-list --count HEAD ...) + 21)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>组件</th><th>版本戳来源</th><th>说明</th></tr></thead><tbody><tr><td>OCOS</td><td><code>-D OC_RELEASE_VERSION/-D OC_KERNEL_BUILD</code> + <code>ocos/kernel/generated/version_gen.h</code>（<code>OC_VERSION_STAMP</code>，由 cmp 守护，版本号一变即强制重编译——<code>-D</code> 标志对 <code>-MMD</code> 依赖跟踪不可见，一个实测发现的过期横幅 bug）</td><td>横幅：<code>Open Cube OS [3.0.0-...]</code></td></tr><tr><td>OCBL</td><td><code>-DOCBL_RELEASE=\\&quot;$(OC_RELEASE_VERSION)\\&quot;</code> + <code>-DOCBL_BUILD=$(OC_KERNEL_BUILD)</code>（<code>ocbl/ocbl.mk</code>）</td><td>源码中的后备字面量 <code>3.0.0-WP05</code>/<code>0</code>；无独立版本号</td></tr><tr><td>OCIRE</td><td><code>OCIRE_VERSION ?= $(OC_RELEASE_VERSION)</code> + <code>ocire/generated/ocire_version_gen.h</code>（<code>OCIRE_STAMP</code>）</td><td>BUG #92 修复——它过去携带自己的字面量，落后了四个里程碑</td></tr><tr><td>OCSE</td><td><code>-DOCSE_RELEASE=\\&quot;$(OC_RELEASE_VERSION)-ocse\\&quot;</code> + <code>OCSE_BUILD=$(OC_KERNEL_BUILD)</code></td><td><strong>唯一</strong>带有独立后缀（<code>-ocse</code>）的组件，因为它是一个披着当前发布号的 v1.0.0 vendor 内嵌内核</td></tr></tbody></table><p><code>+21</code> 偏移使公开构建序列在已发布的 build 274 之上保持单调。各组件的 WP 标签（WP-05、WP-07a……）只存在于文件头注释中，从不出现在交付 横幅里。</p><h2 id="物理内存契约" tabindex="-1">物理内存契约 <a class="header-anchor" href="#物理内存契约" aria-label="Permalink to &quot;物理内存契约&quot;">​</a></h2><p>四个组件从不共享代码，但共享物理地址。这些是承重常量（定义于 <code>ocbl/common/ocbl_boot.h</code>、<code>ocbl/common/ocbl_types.h</code>、 <code>include/ocbl_state.h</code> 以及三份链接脚本）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   0x00500-0x0051F   OCBL A20 测试区</span></span>
<span class="line"><span>   0x00520           stage1 事实：{boot drive, flavor, entry CS}</span></span>
<span class="line"><span>   0x007C00          OCBL stage1（512 B，两种形态共用）</span></span>
<span class="line"><span>   0x007E00..        OCBL core（linker_bios.ld；入口 core_head）</span></span>
<span class="line"><span>   0x30000           64 KiB 读取弹跳窗口；EFI：64-&gt;32 交接 blob</span></span>
<span class="line"><span>   0x40000-0x4FFFF   实模式跳板 + VBE/几何参数暂存区</span></span>
<span class="line"><span>                     （EBDA 与 0x8F000+ 重叠时的后备 PT 块）</span></span>
<span class="line"><span>   0x50000           multiboot2 信息构建缓冲区（OCBL_MBI_BASE；</span></span>
<span class="line"><span>                     OCIRE kexec 时改在 0x80000 重建其 MBI）</span></span>
<span class="line"><span>   0x60000-0x61FFF   E820 / GetMemoryMap 缓冲区</span></span>
<span class="line"><span>   0x62000 / 0x62800 OCBL fs 扇区窗口 / 128 KiB FAT 缓存</span></span>
<span class="line"><span>   0x82800-0x8DFFF   OCBL core 栈（栈顶 0x8E000 - WP06f VMware 修复）</span></span>
<span class="line"><span>   0x8F000-0x94FFF   OCBL 恒等页表（2 MiB 大页，4 GiB）</span></span>
<span class="line"><span>   0x98000  4 KiB    OCST 状态区      魔数 &quot;OCS1&quot; - 内核阶段/</span></span>
<span class="line"><span>                      心跳，由 OCOS 盲写，由 OCBL/OCIRE 读取</span></span>
<span class="line"><span>   0x9B000  4 KiB    OCST 保留区      魔数 &quot;OCB1&quot; - 事后</span></span>
<span class="line"><span>                      引导记录（BOOT_FAILED / USER_REQUEST）</span></span>
<span class="line"><span>   0x9FC00            EBDA（SeaBIOS）</span></span>
<span class="line"><span></span></span>
<span class="line"><span> 载荷放置：</span></span>
<span class="line"><span>   0x100000 (1 MiB)   OCOS 内核 PT_LOAD（链接基址）。OCSE 亦然</span></span>
<span class="line"><span>                      （KERNEL_LMA 0x100000）。两个镜像都必须</span></span>
<span class="line"><span>                      保持在 0x400000 以下（两份脚本中均有</span></span>
<span class="line"><span>                      linker ASSERT）</span></span>
<span class="line"><span>   0x400000-0x600000  “恒等窗口”——用户地址空间把这一虚拟</span></span>
<span class="line"><span>                      范围重映射到空 PT，因此内核镜像永远</span></span>
<span class="line"><span>                      不得长入其中（见 memory.md）</span></span>
<span class="line"><span>   0x800000           mb2 &quot;self&quot; 模块：OCOS 内核 ELF 的原样</span></span>
<span class="line"><span>                      副本（安装器载荷模式）</span></span>
<span class="line"><span>   0x01000000 (16 MiB) OCIRE 链接基址（OCIRE_LMA）——与 OCOS 的</span></span>
<span class="line"><span>                      1 MiB 区间不相交，因此监督者把 OCOS kexec</span></span>
<span class="line"><span>                      到 [0x100000, 0x800000) 不会覆盖自身</span></span></code></pre></div><p>两座监视孤岛在 OCBL 构建的 mb2 内存映射中被划为 <strong>E820 保留</strong>， 因此任何 OS 都不会分配它们；实测表明它们能在 QEMU 热复位中幸存 （这正是全部意义所在——看门狗复位不得抹掉证据）。这两个块的完整 故事见 <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a>，字节布局位于 <code>include/ocbl_state.h</code>。</p><h2 id="引导模式" tabindex="-1">引导模式 <a class="header-anchor" href="#引导模式" aria-label="Permalink to &quot;引导模式&quot;">​</a></h2><p>OCBL 从 <code>ocbl_menu_run()</code> 伸出八条不同的路径；前五条才是严格意义上 的“引导模式”：</p><ol><li><strong>BIOS / El Torito（ISO）</strong>——整个 El Torito 镜像由 SeaBIOS 预加载；0x7C00 处的 stage1 发现 core 已在 0x7E00，打印 <code>OCBL stage1 ok</code>，启用 A20（先 int 15h AX=2401，再端口 0x92， 并做两次独立的别名写入测试——两次都必须失败才判定 A20 关闭）， 然后经由自己的 GDT 跳入 32 位 <code>core_head</code>。</li><li><strong>BIOS / MBR（已安装磁盘）</strong>——静默的 512 字节 stage1 变体。 位于镜像偏移 <code>+0x1A0</code> 的补丁块（<code>&#39;OCBL&#39;</code> 魔数、core LBA、 扇区数——由 <code>ocbl-install</code> 写入）驱动 int 13h AH=42h 把 core 读入 0x7E00。重试循环有意从不复位驱动器：复位会清除 SeaBIOS 的 PIO 回退状态并导致死循环（实测发现的 WP06b b5）。镜像中 446..509 字节保持为零，以便安装时把真实分区表拷贝到其上。</li><li><strong>UEFI</strong>——<code>BOOTX64.EFI</code>，一个由树内 <code>ocbl/elf_to_efi.py</code> 转换器构建的 PE/COFF 应用（从 <code>ld --emit-relocs</code> 导出完整的 <code>.reloc</code> 目录；直接用 <code>ld -m i386pep</code> 的输出只会导出不完整的 目录，OVMF 会错误重定位它）。扫描器、菜单与交接相同，外加 GOP/GetMemoryMap/ExitBootServices 替换以及位于 0x30000 的 64-&gt;32 降级 blob。</li><li><strong>VBR 链式加载（BIOS）</strong>——外来 Windows/Linux/通用卷：读取 卷引导记录，校验 0xAA55，拷贝到 0x7C00，降回实模式并跳转 （GRUB 的 <code>chainloader +1</code> 契约）。只带 <code>BOOTX64.EFI</code> 的 ESP 会被<strong>如实拒绝</strong>（“需要 UEFI 形态”）。</li><li><strong>UEFI 链式加载</strong>——对外来 ESP 加载器执行 <code>LoadImage</code>/ <code>StartImage</code>，boot services 保持存活，并先解除 OVMF 看门狗。</li><li><strong>关机</strong>——通过 OCBL 自有的 FADT/_S5 遍历执行 ACPI S5。</li><li><strong>自动恢复路由</strong>——一条待处理的 BOOT_FAILED 记录使 OCBL 一次性引导 OCIRE 条目，无需菜单交互。</li><li><strong>A/B 槽位选择</strong>——第一个 OCOS 卷上的标志文件协议。</li></ol><h3 id="a-b-槽位与自动回滚" tabindex="-1">A/B 槽位与自动回滚 <a class="header-anchor" href="#a-b-槽位与自动回滚" aria-label="Permalink to &quot;A/B 槽位与自动回滚&quot;">​</a></h3><p>槽位布局（<code>tools/make_ab_disk.sh</code>，文档见 <a href="./ota-ab.html">ota-ab.md</a>）： 分区 1 = 承载 <code>/boot/next_B</code>、<code>/boot/bootfail_B</code>、<code>/boot/ok_B</code> 的 FAT32 标志卷；分区 2 = 槽位 A；分区 3 = 槽位 B。OCBL 的 <code>judge_volume()</code> 实现与 <code>grub.cfg</code> 和 <code>grub-ab.cfg</code> 相同的语义 （三份实现中的标志契约逐字节一致）：</p><ul><li><code>next_B</code> 存在且 <code>bootfail_B</code> 不存在 -&gt; 引导分区 3（槽位 B）；</li><li><code>next_B</code> 与 <code>bootfail_B</code> 同时存在 -&gt; 引导分区 2（槽位 A），标签 后缀 <code>&quot; rollback&quot;</code>——<strong>自动回滚</strong>：槽位 B 内核在引导时悲观地 写入 <code>bootfail_B</code>，只有当 <code>ota_update_confirm_boot()</code> 宣告系统 完全起来后才将其删除，因此在引导中途死掉的 B 内核会在下一次 复位时把机器回滚到 A；</li><li><code>ok_B</code> 存在 -&gt; 槽位 B；</li><li>否则 -&gt; 槽位 A。</li></ul><p>所选槽位的卷会被重新挂载，条目也重新指向它；该磁盘的分区 2/3 已被“槽位占用”，不能再注册自己的条目。同时携带 <code>/boot/opencube.elf</code> 与 <code>/boot/ocire.elf</code> 的卷也会暴露 OCIRE 恢复 条目（WP06g3-4.4——扫描器的短路逻辑过去会把它藏起来）。</p><h2 id="接下来去哪里" tabindex="-1">接下来去哪里 <a class="header-anchor" href="#接下来去哪里" aria-label="Permalink to &quot;接下来去哪里&quot;">​</a></h2><ul><li>加载器链、扫描器类别与交接细节：<a href="./boot-flow.html">boot-flow.md</a></li><li>目录树中每个目录里有什么：<a href="./tree-map.html">tree-map.md</a></li><li>跨组件机制（状态孤岛、看门狗接力、守卫通道）： <a href="./hidden-mechanisms.html">hidden-mechanisms.md</a></li><li>ring 3 API 契约：<a href="./private-headers.html">private-headers.md</a></li><li>OCIRE 深入：<a href="./../dev/ocire.html">../dev/ocire.md</a>；面向用户的一面： <a href="./../manual/boot-modes.html">../manual/boot-modes.md</a>、 <a href="./../manual/recovery.html">../manual/recovery.md</a></li></ul>`,26)])])}const E=a(t,[["render",p]]);export{O as __pageData,E as default};
